const input = $input.first().json;
const ref = new Date(input.reference_time_utc);
const excluded = new Set(['duplicate', 'rejected']);
const byCompany = new Map();
for (const window of input.windows) {
  const start = new Date(ref.getTime() - window.duration_hours * 3600000);
  for (const offer of input.offer_rows || []) {
    const published = new Date(offer.published_at || offer.first_seen_at || offer.updated_at);
    if (!offer.company_key || excluded.has(offer.status) || published < start || published >= ref) continue;
    const key = `${offer.company_key}:${window.window_key}`;
    if (!byCompany.has(key)) byCompany.set(key, { company_key: offer.company_key, window_key: window.window_key, offer_keys: new Set(), new_offer_keys: new Set(), families: new Set(), establishments: new Set(), tension_offer_keys: new Set(), republications: 0, positions: 0, dates: [] });
    const agg = byCompany.get(key);
    const offerKey = offer.canonical_offer_key || offer.offer_key;
    agg.offer_keys.add(offerKey);
    if (offer.dedupe_status === 'new') agg.new_offer_keys.add(offerKey);
    if (offer.dedupe_status === 'republication') agg.republications += 1;
    if (offer.establishment_key) agg.establishments.add(offer.establishment_key);
    agg.positions += Number(offer.declared_positions || 1);
    agg.dates.push(published.toISOString());
    const cls = input.classification_by_offer_key[offer.offer_key] || {};
    for (const fam of JSON.parse(cls.family_ids_json || '[]')) agg.families.add(fam);
    if (cls.is_tension_job) agg.tension_offer_keys.add(offerKey);
  }
}
const signal_upserts = [];
const contributor_upserts = [];
for (const agg of byCompany.values()) {
  const active = agg.offer_keys.size;
  const signal_key = `${agg.company_key}:${agg.window_key}:${input.reference_time_utc}:${input.signal_version}`;
  signal_upserts.push({ signal_key, company_key: agg.company_key, window_key: agg.window_key, signal_version: input.signal_version, active_offer_count: active, new_offer_count: agg.new_offer_keys.size, declared_position_count: agg.positions, job_family_count: agg.families.size, site_count: agg.establishments.size, republication_count: agg.republications, tension_offer_count: agg.tension_offer_keys.size, tension_offer_share: active ? agg.tension_offer_keys.size / active : 0, first_published_at: agg.dates.sort()[0] || null, last_published_at: agg.dates.sort().slice(-1)[0] || null, contributor_offer_keys_json: JSON.stringify([...agg.offer_keys].sort()), confidence: 0.8, computed_at: new Date().toISOString() });
  for (const offer_key of agg.offer_keys) contributor_upserts.push({ contributor_key: `${signal_key}:${offer_key}`, signal_key, offer_key, company_key: agg.company_key, window_key: agg.window_key, signal_version: input.signal_version });
}
return [{ json: { ...input, company_signal_upserts: signal_upserts, company_signal_contributor_upserts: contributor_upserts } }];
